struct Parser {
    line: Vec<u8>,
    data: String,
    event: String,
    id: Option<String>,
    retry: Option<Duration>,
    event_retry: Option<Duration>,
    after_cr: bool,
    first_line: bool,
    limit: usize,
}

impl Default for Parser {
    fn default() -> Self {
        Self {
            line: Vec::new(),
            data: String::new(),
            event: String::new(),
            id: None,
            retry: None,
            event_retry: None,
            after_cr: false,
            first_line: true,
            limit: 1024 * 1024,
        }
    }
}

impl Parser {
    fn push(&mut self, byte: u8) -> io::Result<Option<SseEvent>> {
        if self.after_cr {
            self.after_cr = false;
            if byte == b'\n' {
                return Ok(None);
            }
        }
        if byte != b'\n' && byte != b'\r' {
            if self.line.len()
                + self.data.len()
                + self.event.len()
                + self.id.as_ref().map_or(0, String::len)
                >= self.limit
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "SSE event exceeds the configured size limit",
                ));
            }
            self.line.push(byte);
            return Ok(None);
        }
        self.after_cr = byte == b'\r';
        let line = String::from_utf8_lossy(&self.line);
        let line = if self.first_line {
            line.strip_prefix('\u{feff}').unwrap_or(&line)
        } else {
            &line
        };
        self.first_line = false;
        let result = if line.is_empty() {
            let event = std::mem::take(&mut self.event);
            if self.data.is_empty() {
                None
            } else {
                let retry = self.event_retry.take();
                self.data.pop();
                Some(SseEvent {
                    event: if event.is_empty() {
                        "message".into()
                    } else {
                        event
                    },
                    data: std::mem::take(&mut self.data),
                    id: self.id.clone(),
                    retry,
                })
            }
        } else if line.starts_with(':') {
            None
        } else {
            let (name, value) = line.split_once(':').unwrap_or((line, ""));
            let value = value.strip_prefix(' ').unwrap_or(value);
            match name {
                "data" => {
                    self.data.push_str(value);
                    self.data.push('\n');
                }
                "event" => self.event = value.into(),
                "id" if !value.contains('\0') => self.id = Some(value.into()),
                "retry" if !value.is_empty() && value.bytes().all(|b| b.is_ascii_digit()) => {
                    if let Ok(ms) = value.parse::<u64>() {
                        self.retry = Some(Duration::from_millis(ms));
                        self.event_retry = self.retry;
                    }
                }
                _ => {}
            }
            None
        };
        self.line.clear();
        Ok(result)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(serde::Deserialize, Debug)]
    struct Reply {
        error: Option<String>,
    }

    async fn first(body: &'static str, declares_error: bool) -> Result<Reply, Error> {
        let stream = EventStream::new(StatusCode::OK, HeaderMap::new(), None, Bytes::from(body));
        stream.typed::<Reply>(declares_error).next().await.unwrap()
    }

    #[tokio::test]
    async fn an_error_property_is_an_api_error_unless_the_model_declares_it() {
        let body = "data: {\"text\":\"a\",\"error\":\"partial\"}\n\n";
        let item = first(body, true).await.unwrap();
        assert_eq!(item.error.as_deref(), Some("partial"));
        assert!(first(body, false).await.unwrap_err().api().is_some());
        let error = first("event: error\ndata: {\"error\":\"x\"}\n\n", true).await.unwrap_err();
        assert!(error.api().is_some(), "an `error` event always is");
    }
}
